use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Level { fn color (self) -> anstyle :: Style { match self { Bug | Fatal | Error | DelayedBug => AnsiColor :: BrightRed . on_default () , ForceWarning | Warning => { if cfg ! (windows) { AnsiColor :: BrightYellow . on_default () } else { AnsiColor :: Yellow . on_default () } } Note | OnceNote => AnsiColor :: BrightGreen . on_default () , Help | OnceHelp => AnsiColor :: BrightCyan . on_default () , FailureNote => anstyle :: Style :: new () , Allow | Expect => unreachable ! () , } } pub fn to_str (self) -> & 'static str { match self { Bug | DelayedBug => "error: internal compiler error" , Fatal | Error => "error" , ForceWarning | Warning => "warning" , Note | OnceNote => "note" , Help | OnceHelp => "help" , FailureNote => "failure-note" , Allow | Expect => unreachable ! () , } } pub fn is_failure_note (& self) -> bool { matches ! (* self , FailureNote) } fn can_be_subdiag (& self) -> bool { match self { Bug | DelayedBug | Fatal | Error | ForceWarning | FailureNote | Allow | Expect => false , Warning | Note | Help | OnceNote | OnceHelp => true , } } }